#!/usr/bin/env node
// unflake-ci: zero-dependency npx wrapper. Forwards everything to the
// bundled Python core (./unflake_core, generated by sync.py at pack time).
// Needs a Python 3.9+ on PATH; override discovery with UNFLAKE_PYTHON.
"use strict";

const { spawnSync } = require("node:child_process");
const { existsSync } = require("node:fs");
const { dirname, join } = require("node:path");

const CORE_MAIN = join(dirname(__dirname), "unflake_core", "unflake", "__main__.py");

function candidates() {
  if (process.env.UNFLAKE_PYTHON) return [[process.env.UNFLAKE_PYTHON]];
  if (process.platform === "win32") return [["py", "-3"], ["python"]];
  return [["python3"], ["python"]];
}

function main() {
  if (!existsSync(CORE_MAIN)) {
    console.error(
      "unflake-ci: bundled Python core missing (unflake_core/). " +
      "Reinstall unflake-ci (`npm i -g unflake-ci`) — if you installed from " +
      "git, run `npm run sync` inside npm/ first."
    );
    process.exit(2);
  }
  const args = process.argv.slice(2);
  let spawned = false;
  for (const py of candidates()) {
    const r = spawnSync(py[0], [...py.slice(1), CORE_MAIN, ...args], { stdio: "inherit" });
    if (r.error && r.error.code === "ENOENT") continue; // try next interpreter
    if (r.error) {
      console.error(`unflake-ci: failed to launch ${py[0]}: ${r.error.message}`);
      process.exit(2);
    }
    spawned = true;
    process.exit(r.status === null ? 2 : r.status);
  }
  if (!spawned) {
    console.error(
      "unflake-ci: no Python 3.9+ found (tried: " +
      candidates().map((c) => c.join(" ")).join(", ") +
      "). Install Python or set UNFLAKE_PYTHON=/path/to/python."
    );
    process.exit(2);
  }
}

main();
